mapper.select:
select id, user_id, weight_date, weight_time, kg, tag, created_at
from t_weight
where user_id = #{userId}
order by weight_date desc, weight_time desc, id desc
limit #{limit}

mapper.update:
update t_weight
set kg = #{kg}, weight_time = #{weightTime}
where user_id = #{userId} and weight_date = #{weightDate} and tag = #{tag}
